let lastTime = performance.now();
let accumulator = 0;

function frame(now) {
  requestAnimationFrame(frame);
  let dt = (now - lastTime) / 1000;
  lastTime = now;
  if (!Number.isFinite(dt) || dt < 0) dt = 0;
  dt = Math.min(dt, 0.1);

  accumulator += dt;
  let steps = 0;
  while (accumulator >= STEP && steps < 12) {
    step(STEP);
    accumulator -= STEP;
    steps++;
  }
  if (steps === 12) accumulator = 0;

  updateHud(dt);

  const kmh = state.mode === 'title' ? 0 : playerCar.kmh;
  drawGauge(kmh, state.mode !== 'title' && playerCar.input.brake > 0.1 && playerCar.speed < 5);

  if (state.mode !== 'title') drawMinimap();

  render();
}

