  const perf = await page.evaluate(() => new Promise(resolve => {
    let frames = 0
    const t0 = performance.now()
    const r0 = window.__apex.state.raceTime
    function tick() {
      frames++
      if (performance.now() - t0 < 2000) requestAnimationFrame(tick)
      else resolve({
        frames,
        wallSec: (performance.now() - t0) / 1000,
        gameSec: window.__apex.state.raceTime - r0,
        mode: window.__apex.state.mode,
      })
    }
    requestAnimationFrame(tick)
  }))
  console.log('PERF', JSON.stringify(perf))

  // Put the player on the final lap, just behind the line, then autopilot across it.
  const seeded = await page.evaluate(() => {
    const a = window.__apex
    const car = a.playerCar
    const slot = a.track.gridSlot(140, 0)
    car.pos.x = slot.x
    car.pos.y = slot.y
    car.angle = slot.angle
    car.vel.x = 0
    car.vel.y = 0
    car.speed = 0
    car.prevIndex = slot.index
    car.progIndex = slot.index
    car.prog = a.track.N * 2
    car.laps = 2
    car.lapStart = a.state.raceTime - 12.5
    a.state.raceTime = Math.max(a.state.raceTime, 30)
    return { index: slot.index, N: a.track.N }
  })
  console.log('SEED', JSON.stringify(seeded))

  // Autopilot in-page, mirroring the AI controller, using synthetic key events.
  await page.evaluate(() => {
    const a = window.__apex
    const track = a.track
    const N = track.N
    const held = new Set()
    function setKey(code, on) {
      if (on && !held.has(code)) {
        held.add(code)
        window.dispatchEvent(new KeyboardEvent('keydown', { code, bubbles: true }))
      } else if (!on && held.has(code)) {
        held.delete(code)
        window.dispatchEvent(new KeyboardEvent('keyup', { code, bubbles: true }))
      }
    }
    window.__auto = setInterval(() => {
      const car = a.playerCar
      if (a.state.mode !== 'racing') {
        setKey('KeyW', false); setKey('KeyS', false); setKey('KeyA', false); setKey('KeyD', false)
        return
      }
      const i = car.prevIndex
      const look = Math.max(9, Math.min(46, Math.round((72 + car.speed * 0.5) / track.ds)))
      const p = track.points[(i + look) % N]
      const desired = Math.atan2(p.y - car.pos.y, p.x - car.pos.x)
      let diff = desired - car.angle
      while (diff > Math.PI) diff -= Math.PI * 2
      while (diff < -Math.PI) diff += Math.PI * 2
      const steer = Math.max(-1, Math.min(1, diff * 2.45))
      const target = track.speedProfile[(i + 16) % N] * 0.97
      setKey('KeyA', steer < -0.12)
      setKey('KeyD', steer > 0.12)
      setKey('KeyW', car.speed < target * 0.99)
      setKey('KeyS', car.speed > target * 1.06)
    }, 30)
  })

  let final = null
  const startWait = Date.now()
  while (Date.now() - startWait < 60000) {
    await page.waitForTimeout(500)
    final = await page.evaluate(() => {
      const a = window.__apex
      return {
        mode: a.state.mode,
        laps: a.playerCar.laps,
        finished: a.playerCar.finished,
        finishTime: a.playerCar.finishTime,
        lapTimes: a.playerCar.lapTimes.length,
        speed: Math.round(a.playerCar.kmh),
        pos: a.playerCar.pos,
        resultsVisible: !document.getElementById('resultsScreen').classList.contains('hidden'),
        resultTitle: document.getElementById('resultTitle').textContent,
      }
    })
    if (final.mode === 'results' || final.mode === 'finished') break
  }
  console.log('FINAL', JSON.stringify(final))
  await page.evaluate(() => clearInterval(window.__auto))
  await page.waitForTimeout(500)
  await page.screenshot({ path: join(out, 'check-results.jpg'), type: 'jpeg', quality: 72 })

  // Restart from results should work.
  const againVisible = await page.locator('#againBtn').isVisible()
  console.log('AGAIN visible:', againVisible)
  if (againVisible) {
    await page.click('#againBtn')
    await page.waitForTimeout(400)
    console.log('AFTER AGAIN mode:', await page.evaluate(() => window.__apex.state.mode))
  }

