import { createRequire } from 'node:module'
import { join } from 'node:path'
import { mkdirSync, readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
mkdirSync(out, { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []
try {
  const context = await browser.newContext({ viewport: { width: 1100, height: 700 } })
  const page = await context.newPage()
  page.on('pageerror', e => errors.push('pageerror: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
  page.on('requestfailed', r => errors.push('requestfailed: ' + r.url()))
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await page.waitForTimeout(400)
  await page.screenshot({ path: join(out, 'finish-title.jpg'), type: 'jpeg', quality: 72 })
  console.log('TITLE', await page.evaluate(() => ({
    car: document.getElementById('titleCarName').textContent,
    garageButton: document.getElementById('garageBtn').textContent,
    topKmh: Math.round(window.__apex.playerCar.maxSpeed * 0.42),
  })))

  await page.click('#garageBtn')
  await page.waitForTimeout(300)
  await page.screenshot({ path: join(out, 'finish-garage.jpg'), type: 'jpeg', quality: 72 })
  console.log('GARAGE', await page.evaluate(() => ({
    cards: document.querySelectorAll('.car-card').length,
    locked: document.querySelectorAll('.car-card.locked').length,
    progress: document.getElementById('garageProgress').textContent,
  })))
  await page.click('#garageCloseBtn')

  // Natural race: autopilot the player for three laps.
  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await page.evaluate(() => {
    const a = window.__apex
    const track = a.track
    const N = track.N
    const held = new Set()
    window.__maxOffset = 0
    window.__maxKmh = 0
    function setKey(code, on) {
      if (on && !held.has(code)) { held.add(code); window.dispatchEvent(new KeyboardEvent('keydown', { code, bubbles: true })) }
      else if (!on && held.has(code)) { held.delete(code); window.dispatchEvent(new KeyboardEvent('keyup', { code, bubbles: true })) }
    }
    window.__auto = setInterval(() => {
      const car = a.playerCar
      if (a.state.mode !== 'racing') {
        setKey('KeyW', false); setKey('KeyS', false); setKey('KeyA', false); setKey('KeyD', false)
        return
      }
      const i = car.prevIndex
      const look = Math.max(9, Math.min(46, Math.round((72 + car.speed * 0.5) / track.ds)))
      const p = track.points[(i + look) % N]
      const desired = Math.atan2(p.y - car.pos.y, p.x - car.pos.x)
      let diff = desired - car.angle
      while (diff > Math.PI) diff -= Math.PI * 2
      while (diff < -Math.PI) diff += Math.PI * 2
      const steer = Math.max(-1, Math.min(1, diff * 2.6))
      const target = track.speedProfile[(i + 16) % N] * 0.96
      setKey('KeyA', steer < -0.12)
      setKey('KeyD', steer > 0.12)
      setKey('KeyW', car.speed < target * 0.99)
      setKey('KeyS', car.speed > target * 1.08)
      const near = a.track.nearest(car.pos.x, car.pos.y, car.prevIndex)
      window.__maxOffset = Math.max(window.__maxOffset, Math.abs(near.offset))
      window.__maxKmh = Math.max(window.__maxKmh, car.kmh)
    }, 25)
  })

  // Deterministically advance time while the headless renderer is slow by
  // periodically nudging the race clock is not needed: wait for real finish.
  const started = Date.now()
  let mid = null
  while (Date.now() - started < 75000) {
    await page.waitForTimeout(1000)
    mid = await page.evaluate(() => {
      const a = window.__apex
      return { mode: a.state.mode, laps: a.playerCar.laps, kmh: Math.round(a.playerCar.kmh), raceTime: +a.state.raceTime.toFixed(1) }
    })
    if (mid.laps >= 1 && !globalThis.__shot) {
      globalThis.__shot = true
      await page.screenshot({ path: join(out, 'finish-race.jpg'), type: 'jpeg', quality: 72 })
    }
    if (mid.mode === 'results') break
  }
  await page.evaluate(() => clearInterval(window.__auto))
  console.log('RACE', JSON.stringify(mid))
  await page.waitForTimeout(400)
  await page.screenshot({ path: join(out, 'finish-results.jpg'), type: 'jpeg', quality: 72 })
  console.log('RESULTS', await page.evaluate(() => {
    const a = window.__apex
    return {
      mode: a.state.mode,
      visible: !document.getElementById('resultsScreen').classList.contains('hidden'),
      title: document.getElementById('resultTitle').textContent,
      rows: document.querySelectorAll('#resultRows tr').length,
      best: document.getElementById('resultBest').textContent,
      top: document.getElementById('resultSpeed').textContent,
      unlock: document.getElementById('unlockNote').textContent.trim(),
      unlockVisible: !document.getElementById('unlockNote').classList.contains('hidden'),
      stored: JSON.parse(localStorage.getItem('apex-drift-garage-v1')),
      maxKmh: window.__maxKmh,
      maxOffset: +window.__maxOffset.toFixed(1),
      limit: a.track.width / 2 + 6,
    }
  }))

  // Pick the newly unlocked car from the results garage.
  await page.click('#resultGarageBtn')
  await page.waitForTimeout(300)
  await page.click('.car-card[data-car="jade"]')
  console.log('SELECT', await page.evaluate(() => ({
    name: window.__apex.playerCar.name,
    color: window.__apex.playerCar.color,
    grip: +window.__apex.playerCar.grip.toFixed(2),
  })))
  await page.screenshot({ path: join(out, 'finish-garage-unlocked.jpg'), type: 'jpeg', quality: 72 })
  await page.click('#garageRaceBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await page.waitForTimeout(500)

  // Pause / resume smoke test in the new race.
  await page.keyboard.press('KeyP')
  await page.waitForTimeout(300)
  const paused = await page.evaluate(() => ({ mode: window.__apex.state.mode, visible: !document.getElementById('pauseScreen').classList.contains('hidden') }))
  await page.keyboard.press('KeyP')
  await page.waitForTimeout(300)
  const resumed = await page.evaluate(() => window.__apex.state.mode)
  console.log('PAUSE', JSON.stringify(paused), 'RESUME', resumed)

  // Mobile sanity.
  const mobile = await browser.newContext({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true })
  const mp = await mobile.newPage()
  mp.on('pageerror', e => errors.push('mobile pageerror: ' + e.message))
  mp.on('console', m => { if (m.type() === 'error') errors.push('mobile console: ' + m.text()) })
  await mp.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await mp.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await mp.click('#startBtn')
  await mp.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  const gas = mp.locator('[data-act="throttle"]')
  await gas.dispatchEvent('pointerdown', { pointerId: 1 })
  await mp.waitForTimeout(2200)
  const mobileState = await mp.evaluate(() => ({ mode: window.__apex.state.mode, speed: Math.round(window.__apex.playerCar.kmh), maxKmh: Math.round(window.__apex.playerCar.maxSpeed*0.42) }))
  await gas.dispatchEvent('pointerup', { pointerId: 1 })
  await mp.screenshot({ path: join(out, 'finish-mobile-race.jpg'), type: 'jpeg', quality: 72 })
  console.log('MOBILE', JSON.stringify(mobileState))
