function ribbonGeometry(track, innerOffset, outerOffset, y, vScale = 140) {
  const N = track.N;
  const pos = [];
  const uv = [];
  const idx = [];
  let dist = 0;
  for (let i = 0; i <= N; i++) {
    const k = i % N;
    const p = track.points[k], n = track.normals[k];
    if (i > 0) {
      const prev = track.points[(i-1)%N];
      dist += Math.hypot(p.x-prev.x, p.y-prev.y);
    }
    pos.push(p.x + n.x*innerOffset, y, p.y + n.y*innerOffset);
    pos.push(p.x + n.x*outerOffset, y, p.y + n.y*outerOffset);
    uv.push(0, dist/vScale, 1, dist/vScale);
  }
  for (let i = 0; i < N; i++) {
    const a = i*2, b = a+1, c = a+2, d = a+3;
    idx.push(a, c, b, b, c, d);
  }
  const geo = new THREE.BufferGeometry();
  geo.setAttribute('position', new THREE.Float32BufferAttribute(pos,3));
  geo.setAttribute('uv', new THREE.Float32BufferAttribute(uv,2));
  geo.setIndex(idx);
  geo.computeVertexNormals();
  return geo;
}
