buildParticlePool() {
  const add = (texture, blending, count, depthWrite) => {
    for (let i = 0; i < count; i++) {
      const material = new THREE.SpriteMaterial({
        map: texture,
        color: 0xffffff,
        transparent: true,
        opacity: 0,
        depthWrite,
        blending,
      });
      const sprite = new THREE.Sprite(material);
      sprite.visible = false;
      sprite.frustumCulled = false;
      this.scene.add(sprite);
      this.particleSprites.push(sprite);
    }
  };
  add(this.smokeTexture, THREE.NormalBlending, 220, false);
  add(this.glowTexture, THREE.AdditiveBlending, 120, false);
  this.particleCursor = 0;
}

updateParticles(particles) {
  for (const sprite of this.particleSprites) {
    sprite.visible = false;
    sprite.material.opacity = 0;
  }
  this.particleCursor = 0;

  const take = () => {
    if (this.particleCursor >= this.particleSprites.length) return null;
    return this.particleSprites[this.particleCursor++];
  };

  for (const particle of particles) {
    if (particle.life <= 0) continue;
    const t = clamp(particle.life / particle.maxLife, 0, 1);
    const sprite = take();
    if (!sprite) break;

    if (particle.kind === 'spark') {
      sprite.material.map = this.glowTexture;
      sprite.material.blending = THREE.AdditiveBlending;
      sprite.material.color.set(0xffd27a);
      sprite.material.opacity = 0.95 * t;
      sprite.position.set(particle.x, 3.4 + (1 - t) * 6, particle.y);
      const size = 5 + (1 - t) * 4;
      sprite.scale.set(size, size, 1);
    } else if (particle.kind === 'dust') {
      sprite.material.map = this.dustTexture;
      sprite.material.blending = THREE.NormalBlending;
      sprite.material.color.set(particle.tint === 'green' ? 0x7f9a62 : 0xbba97f);
      sprite.material.opacity = 0.4 * t;
      sprite.position.set(particle.x, 2 + (1 - t) * 4, particle.y);
      const size = particle.size * (1.35 - t * 0.4) * 2.2;
      sprite.scale.set(size, size, 1);
    } else {
      sprite.material.map = this.smokeTexture;
      sprite.material.blending = THREE.NormalBlending;
      sprite.material.color.set(0xe8efec);
      sprite.material.opacity = 0.46 * t;
      sprite.position.set(particle.x, 4 + (1 - t) * 15, particle.y);
      const size = particle.size * (2.1 - t * 0.55) * 2.1;
      sprite.scale.set(size, size, 1);
    }
    sprite.visible = true;
  }
}

