content.text:
.pause-actions .btn-primary { padding: 14px 34px; }
.pause-actions .btn-secondary { padding: 13px 26px; }
.pause-hint { margin: 0; font-size: 11px; color: rgba(160, 184, 184, 0.65); letter-spacing: 0.05em; }

/* ---------- Garage ---------- */

.garage-screen { z-index: 12; }
.garage-card { width: min(780px, 100%); }
.garage-head {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 18px;
}
.garage-head .kicker { margin-bottom: 10px; }
.garage-title {
  margin: 0 0 8px;
  font-family: var(--font-display);
  font-style: italic;
  font-weight: 900;
  font-size: clamp(30px, 4.6vw, 46px);
  letter-spacing: -0.025em;
  line-height: 1;
  color: #fff;
}
.garage-sub {
  margin: 0;
  max-width: 480px;
  font-size: 11.5px;
  line-height: 1.6;
  color: rgba(180, 202, 202, 0.72);
}
.garage-close { flex: 0 0 auto; margin-top: 2px; }
.garage-grid {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 10px;
  margin: 22px 0 20px;
}
.car-card {
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 3px;
  padding: 12px 8px 10px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255, 255, 255, 0.028);
  color: #e9f5f4;
  text-align: center;
  cursor: pointer;
  transition: border-color 0.16s, background 0.16s, transform 0.16s;
}
.car-card:hover:not(.locked) {
  border-color: rgba(58, 226, 255, 0.5);
  background: rgba(58, 226, 255, 0.06);
  transform: translateY(-2px);
}
.car-card.selected {
  border-color: var(--accent);
  background: linear-gradient(180deg, rgba(58, 226, 255, 0.14), rgba(58, 226, 255, 0.04));
  box-shadow: inset 0 0 0 1px rgba(58, 226, 255, 0.35);
}
.car-card.locked {
  opacity: 0.55;
  filter: grayscale(0.65);
  cursor: not-allowed;
  border-style: dashed;
}
.car-card-art {
  display: block;
  width: 42px;
  height: 64px;
  margin-bottom: 3px;
}
.car-card-art svg { display: block; width: 100%; height: 100%; }
.car-card-name {
  font-family: var(--font-display);
  font-size: 12.5px;
  font-weight: 800;
  letter-spacing: 0.12em;
}
.car-card-tag {
  font-family: var(--font-display);
  font-size: 7.5px;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: var(--muted);
}
.car-stats {
  width: 100%;
  display: grid;
  gap: 3px;
  margin-top: 6px;
}
