import { createRequire } from 'node:module'
import { join } from 'node:path'
import { mkdirSync, readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
mkdirSync(out, { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []
try {
  const page = await browser.newPage({ viewport: { width: 1100, height: 700 } })
  page.on('pageerror', e => errors.push('pageerror: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await page.waitForTimeout(2500)
  await page.screenshot({ path: join(out, '3d-title.jpg'), type: 'jpeg', quality: 72 })

  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })

  // Autopilot the player around the circuit.
  await page.evaluate(() => {
    const a = window.__apex
    const track = a.track
    const N = track.N
    const held = new Set()
    window.__maxOffset = 0
    window.__maxKmh = 0
    window.__wallHits = 0
    function setKey(code, on) {
      if (on && !held.has(code)) { held.add(code); window.dispatchEvent(new KeyboardEvent('keydown', { code, bubbles: true })) }
      else if (!on && held.has(code)) { held.delete(code); window.dispatchEvent(new KeyboardEvent('keyup', { code, bubbles: true })) }
    }
    window.__auto = setInterval(() => {
      const car = a.playerCar
      if (a.state.mode !== 'racing') return
      const i = car.prevIndex
      const look = Math.max(9, Math.min(46, Math.round((72 + car.speed * 0.5) / track.ds)))
      const p = track.points[(i + look) % N]
      const desired = Math.atan2(p.y - car.pos.y, p.x - car.pos.x)
      let diff = desired - car.angle
      while (diff > Math.PI) diff -= Math.PI * 2
      while (diff < -Math.PI) diff += Math.PI * 2
      const steer = Math.max(-1, Math.min(1, diff * 2.6))
      const target = track.speedProfile[(i + 16) % N] * 0.96
      setKey('KeyA', steer < -0.12)
      setKey('KeyD', steer > 0.12)
      setKey('KeyW', car.speed < target * 0.99)
      setKey('KeyS', car.speed > target * 1.08)
      const near = track.nearest(car.pos.x, car.pos.y, car.prevIndex)
      window.__maxOffset = Math.max(window.__maxOffset, Math.abs(near.offset))
      window.__maxKmh = Math.max(window.__maxKmh, car.kmh)
      if (car.wallHit > 45) window.__wallHits++
    }, 25)
  })

  let shot = false
  for (let i = 0; i < 70; i++) {
    await page.waitForTimeout(1000)
    const status = await page.evaluate(() => {
      const a = window.__apex
      return { mode: a.state.mode, laps: a.playerCar.laps, raceTime: +a.state.raceTime.toFixed(1) }
    })
    if (!shot && status.laps >= 1 && status.mode === 'racing') {
      shot = true
      await page.waitForTimeout(400)
      await page.screenshot({ path: join(out, '3d-race.jpg'), type: 'jpeg', quality: 72 })
    }
    if (status.mode === 'results') break
  }
  await page.evaluate(() => clearInterval(window.__auto))
  await page.waitForTimeout(500)
  console.log('RACE', await page.evaluate(() => {
    const a = window.__apex
    const c = a.playerCar
    return {
      mode: a.state.mode,
      laps: c.laps,
      lapTimes: c.lapTimes.map(t => +t.toFixed(1)),
      topKmh: c.topSpeed,
      maxKmh: window.__maxKmh,
      maxOffset: +window.__maxOffset.toFixed(1),
      railLimit: a.track.width / 2 + 6,
      wallHits: window.__wallHits,
      resultsVisible: !document.getElementById('resultsScreen').classList.contains('hidden'),
    }
  }))
  await page.screenshot({ path: join(out, '3d-results.jpg'), type: 'jpeg', quality: 72 })

  // Pause and resume from the results garage selection flow.
  await page.click('#resultGarageBtn')
  await page.waitForTimeout(1000)
  await page.screenshot({ path: join(out, '3d-garage-unlocked.jpg'), type: 'jpeg', quality: 72 })
  console.log('GARAGE2', await page.evaluate(() => ({
    unlocked: document.querySelectorAll('.car-card:not(.locked)').length,
    active: window.__apex.garage3d.active,
    calls: window.__apex.garage3d.renderer.info.render.calls,
  })))
  const jade = page.locator('.car-card[data-car="jade"]')
  if (await jade.count()) {
    await jade.click()
    await page.waitForTimeout(400)
    console.log('SELECT', await page.evaluate(() => ({
      selected: document.querySelector('.car-card.selected')?.dataset.car,
      name: window.__apex.playerCar.name,
      viewName: document.getElementById('garageViewName').textContent,
      viewTag: document.getElementById('garageViewTag').textContent,
    })))
    await page.screenshot({ path: join(out, '3d-garage-jade.jpg'), type: 'jpeg', quality: 72 })
  }
  await page.click('#garageRaceBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await page.waitForTimeout(700)
  await page.keyboard.press('KeyP')
  await page.waitForTimeout(400)
  console.log('PAUSE', await page.evaluate(() => ({
    mode: window.__apex.state.mode,
    visible: !document.getElementById('pauseScreen').classList.contains('hidden'),
  })))
  await page.screenshot({ path: join(out, '3d-pause.jpg'), type: 'jpeg', quality: 72 })
  await page.keyboard.press('KeyP')
  await page.waitForTimeout(300)
  console.log('RESUME', await page.evaluate(() => window.__apex.state.mode))

  // Quit to menu from pause.
  await page.keyboard.press('KeyP')
  await page.waitForTimeout(200)
  await page.click('#pauseMenuBtn')
  await page.waitForTimeout(500)
  console.log('MENU', await page.evaluate(() => ({
    mode: window.__apex.state.mode,
    titleVisible: !document.getElementById('titleScreen').classList.contains('hidden'),
    hudLive: document.getElementById('hud').classList.contains('live'),
  })))

  console.log('ERRORS', errors.length ? JSON.stringify(errors.slice(0, 8)) : 'none')
} finally { await browser.close() }

