const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
try {
  const page = await browser.newPage({ viewport: { width: 1100, height: 700 } })
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex)
  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await page.waitForTimeout(7000)
  await page.evaluate(() => {
    const a = window.__apex
    a.state.mode = 'paused'
  })
  await page.waitForTimeout(300)
  const info = await page.evaluate(() => {
    const a = window.__apex
    const car = a.playerCar
    const near = []
    const v = new window.__apex.world3d.camera.position.constructor()
    a.world3d.scene.traverse((obj) => {
      if (!obj.isMesh && !obj.isSprite) return
      if (obj.isInstancedMesh) {
        const m = new obj.matrix.constructor()
        let count = 0
        let first = null
        for (let i = 0; i < obj.count; i++) {
          obj.getMatrixAt(i, m)
          const x = m.elements[12]
          const y = m.elements[13]
          const z = m.elements[14]
          const d = Math.hypot(x - car.pos.x, z - car.pos.y)
          if (d < 120) { count++; if (!first) first = { x: +x.toFixed(1), y: +y.toFixed(1), z: +z.toFixed(1), d: +d.toFixed(1) } }
        }
        if (count) near.push({ kind: 'instanced', geo: obj.geometry.type, count, first, mat: obj.material.color ? '#' + obj.material.color.getHexString() : '?' })
        return
      }
      const p = new obj.position.constructor()
      obj.getWorldPosition(p)
      const d = Math.hypot(p.x - car.pos.x, p.z - car.pos.y)
      if (d < 130) {
        near.push({ kind: obj.type, geo: obj.geometry && obj.geometry.type, d: +d.toFixed(1), pos: [+p.x.toFixed(1), +p.y.toFixed(1), +p.z.toFixed(1)], scale: obj.scale.toArray().map(n => +n.toFixed(1)), mat: obj.material && obj.material.color ? '#' + obj.material.color.getHexString() : '?' })
      }
    })
    return { car: { x: +car.pos.x.toFixed(1), y: +car.pos.y.toFixed(1) }, near: near.slice(0, 40) }
  })
  console.log(JSON.stringify(info, null, 2))
} finally { await browser.close() }

