        modelVisible: model.group.visible,
        modelPos: model.group.position.toArray().map(n => +n.toFixed(0)),
        kmh: a.playerCar.kmh,
      }
    })
    console.log(i, JSON.stringify(info))
    await page.screenshot({ path: join(out, `diag-t${i}.jpg`), type: 'jpeg', quality: 78 })
  }
} finally { await browser.close() }

