import { createRequire } from 'node:module'
import { join } from 'node:path'
import { mkdirSync, readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
mkdirSync(out, { recursive: true })

const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
const errors = []
const attach = (page) => {
  page.on('pageerror', e => errors.push('pageerror: ' + e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push('console: ' + m.text()) })
  page.on('requestfailed', r => errors.push('requestfailed: ' + r.url()))
}

const autopilot = () => {
  const a = window.__apex
  const track = a.track
  const N = track.N
  const held = new Set()
  function setKey(code, on) {
    if (on && !held.has(code)) { held.add(code); window.dispatchEvent(new KeyboardEvent('keydown', { code, bubbles: true })) }
    else if (!on && held.has(code)) { held.delete(code); window.dispatchEvent(new KeyboardEvent('keyup', { code, bubbles: true })) }
  }
  window.__auto = setInterval(() => {
    const car = a.playerCar
    if (a.state.mode !== 'racing') return
    const i = car.prevIndex
    const look = Math.max(9, Math.min(46, Math.round((72 + car.speed * 0.5) / track.ds)))
    const p = track.points[(i + look) % N]
    const desired = Math.atan2(p.y - car.pos.y, p.x - car.pos.x)
    let diff = desired - car.angle
    while (diff > Math.PI) diff -= Math.PI * 2
    while (diff < -Math.PI) diff += Math.PI * 2
    const steer = Math.max(-1, Math.min(1, diff * 2.6))
    const target = track.speedProfile[(i + 16) % N] * 0.96
    setKey('KeyA', steer < -0.12)
    setKey('KeyD', steer > 0.12)
    setKey('KeyW', car.speed < target * 0.99)
    setKey('KeyS', car.speed > target * 1.08)
  }, 25)
}

try {
  /* ---------- Desktop ---------- */
  const page = await browser.newPage({ viewport: { width: 1280, height: 800 } })
  attach(page)
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await page.waitForTimeout(2000)
  await page.screenshot({ path: join(out, 'final3d-title.jpg'), type: 'jpeg', quality: 74 })

  await page.click('#garageBtn')
  await page.waitForTimeout(1200)
  await page.screenshot({ path: join(out, 'final3d-garage.jpg'), type: 'jpeg', quality: 74 })
  await page.click('#garageCloseBtn')

  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await page.evaluate(autopilot)
  for (let i = 0; i < 40; i++) {
    await page.waitForTimeout(700)
    const st = await page.evaluate(() => ({ mode: window.__apex.state.mode, laps: window.__apex.playerCar.laps }))
    if (st.laps >= 1 && st.mode === 'racing') break
  }
  await page.waitForTimeout(900)
  await page.screenshot({ path: join(out, 'final3d-race.jpg'), type: 'jpeg', quality: 74 })
  await page.evaluate(() => clearInterval(window.__auto))

  // Pause, quit to title.
  await page.keyboard.press('KeyP')
  await page.waitForTimeout(300)
  await page.screenshot({ path: join(out, 'final3d-pause.jpg'), type: 'jpeg', quality: 74 })
  await page.click('#pauseMenuBtn')
  await page.waitForTimeout(500)
  console.log('QUIT', await page.evaluate(() => ({
    mode: window.__apex.state.mode,
    title: !document.getElementById('titleScreen').classList.contains('hidden'),
    hudLive: document.getElementById('hud').classList.contains('live'),
    garageActive: window.__apex.garage3d.active,
  })))

  // Restart and finish for results.
  await page.click('#startBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await page.evaluate(autopilot)
  for (let i = 0; i < 80; i++) {
    await page.waitForTimeout(600)
    const st = await page.evaluate(() => window.__apex.state.mode)
    if (st === 'results') break
  }
  await page.evaluate(() => clearInterval(window.__auto))
  await page.waitForTimeout(500)
  await page.screenshot({ path: join(out, 'final3d-results.jpg'), type: 'jpeg', quality: 74 })
  console.log('DESKTOP', await page.evaluate(() => {
    const a = window.__apex
    return {
      mode: a.state.mode,
      results: !document.getElementById('resultsScreen').classList.contains('hidden'),
      laps: a.playerCar.laps,
      topKmh: a.playerCar.topSpeed,
      calls: a.world3d.renderer.info.render.calls,
      triangles: a.world3d.renderer.info.render.triangles,
    }
  }))
  await page.close()

  /* ---------- Mobile ---------- */
  const mobile = await browser.newPage({ viewport: { width: 390, height: 844 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
  attach(mobile)
  await mobile.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await mobile.waitForFunction(() => window.__apex && window.__apex.state.mode === 'title')
  await mobile.waitForTimeout(1600)
  await mobile.screenshot({ path: join(out, 'final3d-mobile-title.jpg'), type: 'jpeg', quality: 72 })

  await mobile.tap('#garageBtn')
  await mobile.waitForTimeout(1200)
  await mobile.screenshot({ path: join(out, 'final3d-mobile-garage.jpg'), type: 'jpeg', quality: 72 })
  console.log('MOBILE_GARAGE', await mobile.evaluate(() => {
    const g = window.__apex.garage3d
    return {
      active: g.active,
      canvas: [g.canvas.width, g.canvas.height],
      renderer: [g.renderer.domElement.width, g.renderer.domElement.height],
      cards: document.querySelectorAll('.car-card').length,
      scrollable: (() => { const l = document.querySelector('.garage-list'); return l.scrollHeight > l.clientHeight })(),
    }
  }))
  await mobile.tap('#garageRaceBtn')
  await mobile.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await mobile.waitForTimeout(600)
  await mobile.evaluate(autopilot)
  await mobile.waitForTimeout(1600)
  await mobile.screenshot({ path: join(out, 'final3d-mobile-race.jpg'), type: 'jpeg', quality: 72 })
  console.log('MOBILE_RACE', await mobile.evaluate(() => {
    const a = window.__apex
    const c = a.playerCar
    const track = a.track
    return {
      mode: a.state.mode,
      kmh: Math.round(c.kmh),
      offset: Math.round(track.nearest(c.pos.x, c.pos.y).offset),
      size: [a.world3d.renderer.domElement.width, a.world3d.renderer.domElement.height],
      dpr: a.world3d.renderer.getPixelRatio(),
      touchVisible: getComputedStyle(document.querySelector('.touch')).display,
    }
  }))
  await mobile.evaluate(() => clearInterval(window.__auto))
  await mobile.close()

  console.log('ERRORS', errors.length ? JSON.stringify(errors.slice(0, 8)) : 'none')
} finally { await browser.close() }

