  await mobile.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await mobile.waitForFunction(() => window.__apex)
  await mobile.waitForTimeout(2500)
  await mobile.screenshot({ path: join(out, 'final3d-mobile-title.jpg'), type: 'jpeg', quality: 72 })
