import { createRequire } from 'node:module'
import { join } from 'node:path'
import { readFileSync } from 'node:fs'
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright')
const require = createRequire(join(runtime, 'package.json'))
const { chromium } = require('playwright')
const config = JSON.parse(readFileSync(join(runtime, 'linux.json'), 'utf8'))
process.env.DISPLAY ||= ':' + readFileSync(join(runtime, 'display'), 'utf8').trim()
const out = '/home/runner/work/PlayGround/PlayGround/screenshots'
const browser = await chromium.launch({ ...config.browser.launchOptions, timeout: 30000 })
try {
  const page = await browser.newPage({ viewport: { width: 844, height: 390 }, isMobile: true, hasTouch: true, deviceScaleFactor: 2 })
  const errors = []
  page.on('pageerror', e => errors.push(e.message))
  page.on('console', m => { if (m.type() === 'error') errors.push(m.text()) })
  await page.goto('http://127.0.0.1:3002/', { waitUntil: 'load', timeout: 45000 })
  await page.waitForFunction(() => window.__apex)
  await page.waitForTimeout(1200)
  await page.screenshot({ path: join(out, 'landscape-title.jpg'), type: 'jpeg', quality: 74 })
  await page.tap('#garageBtn')
  await page.waitForTimeout(900)
  await page.screenshot({ path: join(out, 'landscape-garage.jpg'), type: 'jpeg', quality: 74 })
  console.log('LAYOUT', await page.evaluate(() => {
    const card = document.querySelector('.garage-card')
    const body = document.querySelector('.garage-body')
    const view = document.querySelector('.garage-view')
    const list = document.querySelector('.garage-list')
    const foot = document.querySelector('.garage-foot')
    return {
      card: [card.clientWidth, card.clientHeight, card.scrollHeight],
      body: [body.clientWidth, body.clientHeight],
      view: [view.clientWidth, view.clientHeight],
      list: [list.clientWidth, list.clientHeight, list.scrollHeight],
      foot: [foot.clientWidth, foot.clientHeight],
      viewport: [window.innerWidth, window.innerHeight],
      garageCanvas: [window.__apex.garage3d.canvas.width, window.__apex.garage3d.canvas.height],
    }
  }))
  await page.tap('#garageRaceBtn')
  await page.waitForFunction(() => window.__apex.state.mode === 'racing', { timeout: 12000 })
  await page.waitForTimeout(600)
  await page.screenshot({ path: join(out, 'landscape-race.jpg'), type: 'jpeg', quality: 74 })
  console.log('ERRORS', errors.length ? JSON.stringify(errors.slice(0, 5)) : 'none')
} finally { await browser.close() }

