  g.setLineDash([5, 9]);
  g.stroke(miniPath);
  g.setLineDash([]);

  // Start/finish marker
  const sp = track.points[0];
  const sn = track.normals[0];
  g.strokeStyle = '#f4f1e6';
  g.lineWidth = 3;
  g.beginPath();
  g.moveTo(
    (sp.x - sn.x * track.width * 0.55) * miniScale + miniOffX,
