      car.ramp = hit.ramp;
      car.rampProgress = hit.progress;
      this.integrateAir(car, dt, hit.surface);
      this.updatePitch(car, dt);
      return;
    }

    if (car.ramp) {
      // Just left the ramp footprint.
      const ramp = car.ramp;
      const lx = (car.pos.x - ramp.x) * ramp.tx + (car.pos.y - ramp.z) * ramp.ty;
      const lz = -(car.pos.x - ramp.x) * ramp.ty + (car.pos.y - ramp.z) * ramp.tx;
      const leap = lx > ramp.halfL && Math.abs(lz) <= ramp.halfW + 12;
