      car.ramp = null;
      car.rampProgress = 0;
      if (height > 1.5) {
        car.airborne = true;
        car.vy = leap ? Math.max(car.climbRate || 0, 0) : 0;
        car.y = height;
        this.integrateAir(car, dt, 0);
      } else {
        car.y = 0;
        car.vy = 0;
        car.airborne = false;
      }
      this.updatePitch(car, dt);
      return;
    }

    if (car.airborne) {
      this.integrateAir(car, dt, 0);
      this.updatePitch(car, dt);
      return;
    }

    car.y = 0;
    car.vy = 0;
    this.updatePitch(car, dt);
  }

  integrateAir(car, dt, ground) {
    car.vy -= GRAVITY * dt;
    car.y += car.vy * dt;
    if (car.y <= ground) {
      const impact = -car.vy;
      car.y = ground;
      car.vy = 0;
      car.airborne = false;
      if (impact > 45) {
        car.landImpact = Math.max(car.landImpact || 0, impact);
        car.bump = Math.max(car.bump, 0.75);
