function makeRampTexture() {
  const rnd = mulberry32(731);
  return makeTexture(256, 128, (g, w, h) => {
    g.fillStyle = '#353b41';
    g.fillRect(0, 0, w, h);
    for (let i = 0; i < 1500; i++) {
      const v = rnd();
      g.fillStyle =
        v < 0.5 ? 'rgba(16, 19, 22, 0.26)' : 'rgba(150, 158, 166, 0.14)';
      const s = 0.5 + rnd() * 1.6;
      g.fillRect(rnd() * w, rnd() * h, s, s);
    }

    // Hazard strips along both long edges.
    for (const y of [0, h - 13]) {
      g.fillStyle = '#e6b32c';
      g.fillRect(0, y, w, 13);
      g.fillStyle = '#1a1d1f';
      for (let x = -h; x < w + h; x += 26) {
        g.beginPath();
        g.moveTo(x, y + 13);
        g.lineTo(x + 13, y);
        g.lineTo(x + 24, y);
        g.lineTo(x + 11, y + 13);
        g.closePath();
        g.fill();
      }
    }

    // Forward-pointing chevrons.
    g.lineWidth = 12;
    g.lineJoin = 'miter';
    g.strokeStyle = '#f2c53b';
    for (let i = -1; i < 4; i++) {
      const x = 44 + i * 68;
      g.beginPath();
      g.moveTo(x - 30, 27);
      g.lineTo(x, 64);
      g.lineTo(x - 30, 101);
      g.stroke();
    }
    g.lineWidth = 3;
    g.strokeStyle = 'rgba(255, 246, 205, 0.7)';
    for (let i = -1; i < 4; i++) {
      const x = 44 + i * 68;
      g.beginPath();
      g.moveTo(x - 30, 27);
      g.lineTo(x, 64);
      g.lineTo(x - 30, 101);
      g.stroke();
    }
  }, { clampEdge: true });
}

